import{_ as t,c as r,o,ae as a}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Get Category Tree","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-category-tree","title":"Get Category Tree","description":"Retrieve the active category tree as a nested structure, scoped to a parent.","request":"curl -X GET \\"http://localhost/api/shop/category-trees?parentId=1&depth=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 8,\\n    \\"position\\": 2,\\n    \\"status\\": 1,\\n    \\"displayMode\\": \\"products_and_description\\",\\n    \\"_lft\\": 14,\\n    \\"_rgt\\": 15,\\n    \\"createdAt\\": \\"2024-04-19T19:06:12+05:30\\",\\n    \\"updatedAt\\": \\"2026-01-03T00:53:45+05:30\\",\\n    \\"url\\": \\"http://localhost/electronics\\",\\n    \\"translation\\": {\\n      \\"id\\": 60,\\n      \\"categoryId\\": 8,\\n      \\"name\\": \\"Electronics\\",\\n      \\"slug\\": \\"electronics\\",\\n      \\"urlPath\\": \\"electronics\\",\\n      \\"description\\": \\"<p>Discover a wide range of cutting-edge electronics…</p>\\",\\n      \\"metaTitle\\": \\"Electronics\\",\\n      \\"metaDescription\\": \\"\\",\\n      \\"metaKeywords\\": \\"electronics, electronics-keyboard\\",\\n      \\"locale\\": \\"en\\"\\n    },\\n    \\"children\\": []\\n  },\\n  {\\n    \\"id\\": 23,\\n    \\"position\\": 3,\\n    \\"status\\": 1,\\n    \\"displayMode\\": \\"products_and_description\\",\\n    \\"_lft\\": 18,\\n    \\"_rgt\\": 25,\\n    \\"createdAt\\": \\"2025-09-03T18:13:50+05:30\\",\\n    \\"updatedAt\\": \\"2025-09-03T23:56:45+05:30\\",\\n    \\"url\\": \\"http://localhost/furniture\\",\\n    \\"translation\\": {\\n      \\"id\\": 195,\\n      \\"categoryId\\": 23,\\n      \\"name\\": \\"Furniture\\",\\n      \\"slug\\": \\"furniture\\",\\n      \\"urlPath\\": \\"\\",\\n      \\"description\\": \\"<p>Discover our wide range of furniture…</p>\\",\\n      \\"metaTitle\\": \\"\\",\\n      \\"metaDescription\\": \\"\\",\\n      \\"metaKeywords\\": \\"\\",\\n      \\"locale\\": \\"en\\"\\n    },\\n    \\"children\\": [\\n      {\\n        \\"id\\": 21,\\n        \\"position\\": 5,\\n        \\"status\\": 1,\\n        \\"displayMode\\": \\"products_and_description\\",\\n        \\"url\\": \\"http://localhost/leather-sofa\\",\\n        \\"translation\\": {\\n          \\"id\\": 177,\\n          \\"categoryId\\": 21,\\n          \\"name\\": \\"Leather Sofa\\",\\n          \\"slug\\": \\"leather-sofa\\",\\n          \\"urlPath\\": \\"furniture/leather-sofa\\",\\n          \\"locale\\": \\"en\\"\\n        },\\n        \\"children\\": []\\n      }\\n    ]\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."},{"error":"403 Forbidden","cause":"Storefront key inactive or rate-limited","solution":"Activate the key or wait for the rate limit window to reset."}]}]},"headers":[],"relativePath":"api/rest-api/shop/categories/get-category-tree.md","filePath":"api/rest-api/shop/categories/get-category-tree.md"}'),d={name:"api/rest-api/shop/categories/get-category-tree.md"};function n(i,e,s,c,l,h){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="get-category-tree" tabindex="-1">Get Category Tree <a class="header-anchor" href="#get-category-tree" aria-label="Permalink to &quot;Get Category Tree&quot;">​</a></h1><p>Retrieve the <strong>active</strong> category tree as a nested structure. Children are inlined recursively up to the requested depth, so a single request renders the full menu/sidebar without follow-up calls.</p><p>Three things decide what this endpoint returns:</p><ul><li><strong>The URL is plural and hyphenated</strong> — <code>/category-trees</code>.</li><li><strong>Only active categories appear.</strong> The tree is filtered to <code>status = 1</code> at every level, so a disabled category and everything under it is absent.</li><li><strong><code>parentId</code> is optional.</strong> Supplying it returns that category&#39;s children; omitting it returns the root categories instead. An unknown <code>parentId</code> returns an empty array.</li></ul><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/category-trees</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Storefront API key (<code>pk_storefront_…</code>)</td></tr><tr><td><code>X-Locale</code></td><td>No</td><td>Override request locale (default: channel locale)</td></tr><tr><td><code>X-Channel</code></td><td>No</td><td>Override channel scope</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>parentId</code></td><td>integer</td><td>—</td><td><strong>Required.</strong> Return descendants of this category. Use the root category ID (e.g. <code>1</code>) for the full menu.</td></tr><tr><td><code>depth</code></td><td>integer</td><td>4</td><td>Maximum nesting depth — how many child levels to inline</td></tr></tbody></table><p>Pagination headers are not emitted on this endpoint. The whole tree comes back in one response, however deep it runs.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code> — JSON array of root nodes, each with a recursive <code>children[]</code> array.</p><h3 id="tree-node-fields" tabindex="-1">Tree Node Fields <a class="header-anchor" href="#tree-node-fields" aria-label="Permalink to &quot;Tree Node Fields&quot;">​</a></h3><p>Each node carries a slimmer shape than the flat-list category endpoint — <code>parent</code>, <code>translations[]</code>, <code>filterableAttributes</code>, and image URLs are <strong>not</strong> included. Use <a href="/api/rest-api/shop/categories/get-categories.html">Get Categories</a> when you need those.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Category primary key</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order</td></tr><tr><td><code>status</code></td><td>boolean (0/1)</td><td>Always <code>1</code></td></tr><tr><td><code>displayMode</code></td><td>string</td><td><code>products_and_description</code>, <code>products</code>, or <code>description_only</code></td></tr><tr><td><code>url</code></td><td>string</td><td>Storefront URL</td></tr><tr><td><code>_lft</code>, <code>_rgt</code></td><td>integer</td><td>Nested-set tree pointers (internal; safe to ignore)</td></tr><tr><td><code>createdAt</code></td><td>string (ISO-8601)</td><td>Creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td>string (ISO-8601)</td><td>Last update timestamp</td></tr><tr><td><code>translation</code></td><td>object</td><td>Inline translation for the request locale</td></tr><tr><td><code>children</code></td><td>array</td><td>Recursive child nodes — empty <code>[]</code> at the leaf or at <code>depth</code> cap</td></tr></tbody></table><p>The inline <code>translation</code> contains the same fields as the inline translation on <a href="/api/rest-api/shop/categories/get-categories.html#inline-translation-fields">Get Categories</a>.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li>Render a header / sidebar / mega-menu in one request.</li><li>Build a sitemap of every navigable category for SEO crawling.</li><li>Draw a recursive &quot;browse-by-category&quot; tree in admin tooling.</li></ul><h2 id="differences-vs-categories" tabindex="-1">Differences vs <code>/categories</code> <a class="header-anchor" href="#differences-vs-categories" aria-label="Permalink to &quot;Differences vs `/categories`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th><code>/categories</code> (flat)</th><th><code>/category-trees</code> (nested)</th></tr></thead><tbody><tr><td>Shape</td><td>Flat array, paginated</td><td>Nested tree, no pagination</td></tr><tr><td><code>parent_id</code> / <code>parentId</code></td><td>Optional</td><td><strong>Required</strong> (else returns <code>[]</code>)</td></tr><tr><td>Depth control</td><td>n/a (one level at a time via <code>?parent_id</code>)</td><td><code>?depth=N</code></td></tr><tr><td>Embeds</td><td><code>parent</code>, <code>translations[]</code>, <code>filterableAttributes</code>, <code>logoUrl</code>, <code>children</code> (inline 1 level)</td><td>Recursive <code>children[]</code>, single <code>translation</code></td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Use this rather than following <code>children</code> from the flat listing</strong> — the tree nests real objects, so a full menu is one request instead of one per level.</li><li><strong>Read <code>translation.name</code> and <code>translation.slug</code></strong> — the node itself carries no display name.</li><li><strong>Ignore <code>_lft</code> and <code>_rgt</code></strong> — they are internal ordering pointers, not something a client should sort on; <code>position</code> is the display order.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/categories/get-categories.html">Get Categories</a> — flat collection</li><li><a href="/api/rest-api/shop/categories/get-categories.html">Get Categories</a> — the flat listing, and the single-category endpoint with full detail</li><li><a href="/api/rest-api/shop/products/get-products.html">Get Products</a> — <code>?category_id=N</code> to scope products</li></ul>',25)]))}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
